CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
INSERT OR IGNORE INTO schema_migrations VALUES (1, CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS roles(name TEXT PRIMARY KEY);
INSERT OR IGNORE INTO roles VALUES ('SUPERADMIN'),('ADMIN'),('OPERATOR'),('VIEWER');
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT REFERENCES roles(name), must_change INTEGER NOT NULL DEFAULT 0, disabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id) ON DELETE CASCADE, csrf TEXT NOT NULL, expires REAL NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts(identity TEXT PRIMARY KEY, failures INTEGER NOT NULL, until REAL NOT NULL);
CREATE TABLE IF NOT EXISTS repositories(id TEXT PRIMARY KEY, name TEXT NOT NULL, provider TEXT NOT NULL, url TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, config TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'DISABLED', last_sync REAL, duration REAL, found INTEGER NOT NULL DEFAULT 0, error TEXT);
CREATE TABLE IF NOT EXISTS repository_credentials(repository_id TEXT PRIMARY KEY REFERENCES repositories(id) ON DELETE CASCADE, secret_ref TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS discovered_models(id TEXT PRIMARY KEY, repository_id TEXT REFERENCES repositories(id), upstream_key TEXT NOT NULL, revision TEXT NOT NULL, metadata TEXT NOT NULL, discovered_at REAL NOT NULL, last_checked REAL NOT NULL, UNIQUE(repository_id,upstream_key,revision));
CREATE TABLE IF NOT EXISTS model_artifacts(id TEXT PRIMARY KEY REFERENCES discovered_models(id), url TEXT NOT NULL, size INTEGER NOT NULL, sha256 TEXT, format TEXT NOT NULL DEFAULT 'GGUF');
CREATE TABLE IF NOT EXISTS installed_models(id TEXT PRIMARY KEY REFERENCES discovered_models(id), path TEXT NOT NULL, sha256 TEXT NOT NULL, installed_at REAL NOT NULL, state TEXT NOT NULL, published INTEGER NOT NULL DEFAULT 0, notes TEXT NOT NULL DEFAULT '', config TEXT NOT NULL DEFAULT '{}', gguf TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS downloads(id TEXT PRIMARY KEY, model_id TEXT NOT NULL REFERENCES discovered_models(id), state TEXT NOT NULL, downloaded INTEGER NOT NULL DEFAULT 0, total INTEGER NOT NULL, speed REAL NOT NULL DEFAULT 0, eta REAL, attempts INTEGER NOT NULL DEFAULT 0, next_retry REAL NOT NULL DEFAULT 0, error TEXT, created_at REAL NOT NULL, updated_at REAL NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS single_download ON downloads(model_id) WHERE state IN ('QUEUED','DOWNLOADING','VERIFYING','PAUSED');
CREATE TABLE IF NOT EXISTS runtime_instances(id TEXT PRIMARY KEY, model_id TEXT NOT NULL REFERENCES installed_models(id), state TEXT NOT NULL, pid INTEGER, port INTEGER NOT NULL, config TEXT NOT NULL, error TEXT, started_at REAL, desired TEXT NOT NULL DEFAULT 'STOPPED');
CREATE UNIQUE INDEX IF NOT EXISTS runtime_per_model ON runtime_instances(model_id);
CREATE TABLE IF NOT EXISTS audit_events(id INTEGER PRIMARY KEY AUTOINCREMENT, payload TEXT NOT NULL, previous TEXT NOT NULL, digest TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS audit_no_update BEFORE UPDATE ON audit_events BEGIN SELECT RAISE(ABORT,'audit is append-only'); END;
CREATE TRIGGER IF NOT EXISTS audit_no_delete BEFORE DELETE ON audit_events BEGIN SELECT RAISE(ABORT,'audit is append-only'); END;
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS benchmark_results(id TEXT PRIMARY KEY, created_at REAL NOT NULL, result TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS alerts(id TEXT PRIMARY KEY, severity TEXT NOT NULL, message TEXT NOT NULL, created_at REAL NOT NULL, resolved INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS watchlists(id TEXT PRIMARY KEY, name TEXT NOT NULL, filters TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS system_jobs(id TEXT PRIMARY KEY, action TEXT NOT NULL, payload TEXT NOT NULL, state TEXT NOT NULL, result TEXT, created_at REAL NOT NULL);
